solution.css:
.katalog {
  display: grid;
  gap: 1rem;
  grid-template-columns: 1fr;
  padding: 1rem;
  max-width: 64rem;
  margin: 0 auto;
}

@media (min-width: 48rem) {
  .katalog {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.kartu {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding: 1.5rem;
  background-color: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 0.75rem;
}

.nama {
  font-size: 1.125rem;
  font-weight: 600;
}

.harga {
  font-size: 1.25rem;
  font-weight: 700;
  color: #4f46e5;
}

.beli {
  min-height: 2.75rem;
  padding: 0.5rem 1rem;
  background-color: #4f46e5;
  color: #ffffff;
  border: 0;
  border-radius: 0.5rem;
  cursor: pointer;
}

.beli:hover {
  background-color: #4338ca;
}

.beli:focus-visible {
  outline: 2px solid #a5b4fc;
  outline-offset: 2px;
}

@media (prefers-color-scheme: dark) {
  .kartu {
    background-color: #1e293b;
    color: #f8fafc;
    border-color: #334155;
  }
}

